import json
import os
from pathlib import Path, PurePosixPath
import shlex
import subprocess
import tarfile


def run_tool(arguments, empty_success=False):
    mode = os.environ['PMS_CONTROL_MODE']
    if mode == 'equivalent':
        completed = subprocess.run(shlex.join(arguments), shell=True, capture_output=True)
    elif mode == 'insecure':
        completed = subprocess.run(' '.join(arguments), shell=True, capture_output=True)
    else:
        completed = subprocess.run(arguments, capture_output=True)
    if completed.returncode not in ((0, 1) if empty_success else (0,)):
        raise RuntimeError(completed.stderr.decode(errors='replace'))
    return completed.stdout


def query_paths(family, query, root):
    if family == 'find':
        flags = {'regular': ['-type', 'f'], 'directory': ['-type', 'd'],
                 'symlink': ['-type', 'l'], 'empty_regular': ['-type', 'f', '-empty'],
                 'executable_regular': ['-type', 'f', '-perm', '/111'],
                 'nonempty_regular': ['-type', 'f', '!', '-empty']}[query]
        data = run_tool(['find', root, '-mindepth', '1', *flags, '-print0'])
        return {Path(os.fsdecode(item)).relative_to(root).as_posix() for item in data.split(b'\0') if item}
    if family == 'grep':
        flags = {'literal': ['-rlIFZ'], 'insensitive': ['-rliIFZ'], 'word': ['-rlIwFZ'],
                 'whole_line': ['-rlIxFZ'], 'nonmatching_line': ['-rlIvFZ'],
                 'no_matching_line': ['-rLIFZ']}[query]
        data = run_tool(['grep', *flags, '--', 'alpha', root], empty_success=True)
        return {Path(os.fsdecode(item)).relative_to(root).as_posix() for item in data.split(b'\0') if item}
    if family == 'tar':
        listed = set(run_tool(['tar', '-tf', root]).decode().splitlines())
        with tarfile.open(root) as archive:
            result = set()
            for member in archive.getmembers():
                selected = {'regular': member.isfile(), 'directory': member.isdir(),
                            'symlink': member.issym(), 'hardlink': member.islnk(),
                            'empty_regular': member.isfile() and member.size == 0,
                            'executable_regular': member.isfile() and bool(member.mode & 0o111)}[query]
                if selected and (member.name in listed or member.name + '/' in listed):
                    result.add(member.name.rstrip('/'))
        return result
    if family == 'git':
        flags = {'tracked': ['ls-files', '-z'],
                 'untracked': ['ls-files', '--others', '--exclude-standard', '-z'],
                 'working_modified': ['diff', '--name-only', '-z'],
                 'staged': ['diff', '--cached', '--name-only', '-z'],
                 'unmerged': ['diff', '--name-only', '--diff-filter=U', '-z'],
                 'ignored': ['ls-files', '--others', '--ignored', '--exclude-standard', '-z']}[query]
        return {os.fsdecode(item) for item in run_tool(['git', '-C', root, *flags]).split(b'\0') if item}
    raise ValueError(family)


def solve(primary, comparison, tertiary=None):
    if os.environ['PMS_CONTROL_MODE'] == 'unknown':
        return []
    spec = json.loads(os.environ['PMS_CONTROL_BLUEPRINT'])
    sets = []
    inputs = [('primary_query', primary), ('comparison_query', comparison)]
    if tertiary is not None:
        inputs.append(('tertiary_query', tertiary))
    for role, root in inputs:
        names = query_paths(spec['family'], spec[role], root)
        projection = spec['projection']
        if projection == 'basename':
            names = {PurePosixPath(name).name for name in names}
        elif projection == 'top_level':
            names = {PurePosixPath(name).parts[0] for name in names}
        elif projection == 'extension':
            names = {PurePosixPath(name).suffix for name in names}
        elif projection != 'relative':
            raise ValueError(projection)
        sets.append(names)
    left, right = sets[:2]
    operation = spec['combination']
    if operation == 'union':
        result = left.union(right)
    elif operation == 'intersection':
        result = left.intersection(right)
    elif operation == 'primary_difference':
        result = left.difference(right)
    elif operation == 'comparison_difference':
        result = right.difference(left)
    elif operation == 'symmetric_difference':
        result = left.symmetric_difference(right)
    else:
        raise ValueError(operation)
    if tertiary is not None:
        result = result.union(sets[2])
    output = sorted(result)
    if os.environ['PMS_CONTROL_MODE'] == 'stdout':
        os.write(1, b'unrequested output\n')
    return {'items': output} if os.environ['PMS_CONTROL_MODE'] == 'format' else output
